package com.empcontrol.agent.listener;
import com.empcontrol.agent.metrics.MetricsCollector; import com.empcontrol.agent.net.AgentClient; import org.bukkit.event.*; import org.bukkit.event.player.*; import java.util.Map;
public final class PlayerStatsListener implements Listener { private final MetricsCollector metrics; private final AgentClient client; public PlayerStatsListener(MetricsCollector metrics, AgentClient client){this.metrics=metrics;this.client=client;} @EventHandler public void join(PlayerJoinEvent e){ metrics.joined(); client.send("consoleLog", Map.of("level","INFO","source","player","category","PLAYER","message",e.getPlayer().getName()+" joined")); } @EventHandler public void quit(PlayerQuitEvent e){ metrics.left(); client.send("consoleLog", Map.of("level","INFO","source","player","category","PLAYER","message",e.getPlayer().getName()+" left")); } }
